import type { EditxEngine } from "@editx/engine";
import { SHAPE_RECT_CORNER_RADIUS } from "@editx/engine";
import {
  AlignCenterHorizontal,
  AlignCenterVertical,
  AlignEndHorizontal,
  AlignEndVertical,
  AlignStartHorizontal,
  AlignStartVertical,
  ChevronDown,
  ChevronsDown,
  ChevronsUp,
  ChevronUp,
} from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useState } from "react";
import { cn } from "../../utils/cn";
import { InputGroup } from "../ui/input-group";
import { Section } from "../ui/section";
import { SliderField } from "../ui/slider-field";
import { Tooltip, TooltipContent, TooltipTrigger } from "../ui/tooltip";

interface PositionPropertyPanelProps {
  engine: EditxEngine;
  blockId: number;
  onBringForward?: () => void;
  onSendBackward?: () => void;
  onBringToFront?: () => void;
  onSendToBack?: () => void;
  onAlign?: (direction: "left" | "center" | "right" | "top" | "middle" | "bottom") => void;
}

interface PosState {
  x: number;
  y: number;
  width: number;
  height: number;
  cornerRadius: number;
  shapeKind: string;
}

function readPos(engine: EditxEngine, blockId: number): PosState {
  const pos = engine.block.getPosition(blockId);
  const size = engine.block.getSize(blockId);

  let cornerRadius = 0;
  let shapeKind = engine.block.getKind(blockId);
  const shapeId = engine.block.getShape(blockId);
  if (shapeId != null) {
    shapeKind = engine.block.getKind(shapeId) || shapeKind;
    if (shapeKind === "rect") {
      cornerRadius = engine.block.getFloat(shapeId, SHAPE_RECT_CORNER_RADIUS) ?? 0;
    }
  }

  return { x: pos.x, y: pos.y, width: size.width, height: size.height, cornerRadius, shapeKind };
}

export const PositionPropertyPanel: React.FC<PositionPropertyPanelProps> = ({
  engine,
  blockId,
  onBringForward,
  onSendBackward,
  onBringToFront,
  onSendToBack,
  onAlign,
}) => {
  const [state, setState] = useState(() => readPos(engine, blockId));

  useEffect(() => {
    setState(readPos(engine, blockId));
  }, [engine, blockId]);

  // Re-sync when undo/redo changes engine state
  useEffect(() => {
    return engine.onHistoryChanged(() => setState(readPos(engine, blockId)));
  }, [engine, blockId]);

  const update = useCallback(() => setState(readPos(engine, blockId)), [engine, blockId]);

  const handlePosX = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = parseFloat(e.target.value);
      if (!Number.isNaN(val)) {
        engine.block.setPosition(blockId, val, state.y);
        update();
      }
    },
    [engine, blockId, state.y, update],
  );

  const handlePosY = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = parseFloat(e.target.value);
      if (!Number.isNaN(val)) {
        engine.block.setPosition(blockId, state.x, val);
        update();
      }
    },
    [engine, blockId, state.x, update],
  );

  const handleWidth = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = parseFloat(e.target.value);
      if (!Number.isNaN(val) && val > 0) {
        engine.block.setSize(blockId, val, state.height);
        update();
      }
    },
    [engine, blockId, state.height, update],
  );

  const handleHeight = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = parseFloat(e.target.value);
      if (!Number.isNaN(val) && val > 0) {
        engine.block.setSize(blockId, state.width, val);
        update();
      }
    },
    [engine, blockId, state.width, update],
  );

  const handleCornerRadius = useCallback(
    ([v]: number[]) => {
      const shapeId = engine.block.getShape(blockId);
      if (shapeId != null) {
        engine.block.setFloat(shapeId, SHAPE_RECT_CORNER_RADIUS, v);
        update();
      }
    },
    [engine, blockId, update],
  );

  return (
    <div className="flex flex-col gap-4">
      {/* Position */}
      <Section label="Position">
        <div className="grid grid-cols-2 gap-2">
          <InputGroup label="X" value={state.x} onChange={handlePosX} />
          <InputGroup label="Y" value={state.y} onChange={handlePosY} />
        </div>
      </Section>

      {/* Size */}
      <Section label="Size">
        <div className="grid grid-cols-2 gap-2">
          <InputGroup label="W" value={state.width} onChange={handleWidth} />
          <InputGroup label="H" value={state.height} onChange={handleHeight} />
        </div>
      </Section>

      {/* Corner Radius (rect only) */}
      {state.shapeKind === "rect" && (
        <SliderField
          label="Border Radius"
          value={state.cornerRadius}
          min={0}
          max={Math.min(state.width, state.height) / 2}
          step={1}
          onChange={(v) => handleCornerRadius([v])}
        />
      )}

      {/* Move (z-order) */}
      {(onBringForward || onSendBackward || onBringToFront || onSendToBack) && (
        <div className="flex flex-col gap-1.5">
          <span className="text-sm font-medium text-muted-foreground @5xl/editor:text-base">
            Move
          </span>
          <div className="flex gap-1">
            <ZOrderButton
              icon={<ChevronsUp className="h-4 w-4" />}
              label="Bring to Front"
              onClick={onBringToFront}
            />
            <ZOrderButton
              icon={<ChevronUp className="h-4 w-4" />}
              label="Bring Forward"
              onClick={onBringForward}
            />
            <ZOrderButton
              icon={<ChevronDown className="h-4 w-4" />}
              label="Send Backward"
              onClick={onSendBackward}
            />
            <ZOrderButton
              icon={<ChevronsDown className="h-4 w-4" />}
              label="Send to Back"
              onClick={onSendToBack}
            />
          </div>
        </div>
      )}

      {/* Align to Page */}
      {onAlign && (
        <div className="flex flex-col gap-1.5">
          <span className="text-sm font-medium text-muted-foreground @5xl/editor:text-base">
            Align to Page
          </span>
          <div className="grid grid-cols-3 gap-1">
            <ZOrderButton
              icon={<AlignStartVertical className="h-4 w-4" />}
              label="Align Left"
              onClick={() => onAlign("left")}
            />
            <ZOrderButton
              icon={<AlignCenterVertical className="h-4 w-4" />}
              label="Align Center"
              onClick={() => onAlign("center")}
            />
            <ZOrderButton
              icon={<AlignEndVertical className="h-4 w-4" />}
              label="Align Right"
              onClick={() => onAlign("right")}
            />
            <ZOrderButton
              icon={<AlignStartHorizontal className="h-4 w-4" />}
              label="Align Top"
              onClick={() => onAlign("top")}
            />
            <ZOrderButton
              icon={<AlignCenterHorizontal className="h-4 w-4" />}
              label="Align Middle"
              onClick={() => onAlign("middle")}
            />
            <ZOrderButton
              icon={<AlignEndHorizontal className="h-4 w-4" />}
              label="Align Bottom"
              onClick={() => onAlign("bottom")}
            />
          </div>
        </div>
      )}
    </div>
  );
};

const ZOrderButton: React.FC<{
  icon: React.ReactNode;
  label: string;
  onClick?: () => void;
}> = ({ icon, label, onClick }) => (
  <Tooltip>
    <TooltipTrigger asChild>
      <button
        type="button"
        onClick={onClick}
        disabled={!onClick}
        className={cn(
          "flex items-center justify-center h-8 w-8 rounded-md transition-colors",
          onClick
            ? "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
            : "text-muted-foreground/40 cursor-not-allowed",
        )}
      >
        {icon}
      </button>
    </TooltipTrigger>
    <TooltipContent side="bottom">{label}</TooltipContent>
  </Tooltip>
);
