import type { EffectType } from "../../block/block.types";
import type { BlockStore } from "../../block/block-store";
import type { Patch } from "../../history-manager";
import { PatchCommand } from "./patch-command";

export class CreateEffectCommand extends PatchCommand {
  #store: BlockStore;
  #effectType: EffectType;
  #createdId: number | null = null;

  constructor(store: BlockStore, effectType: EffectType) {
    super();
    this.#store = store;
    this.#effectType = effectType;
  }

  do(): Patch[] {
    const id = this.#store.createEffect(this.#effectType);
    this.#createdId = id;
    return [
      {
        id: id,
        before: null,
        after: this.#store.snapshot(id),
      },
    ];
  }

  getCreatedId(): number | null {
    return this.#createdId;
  }
}
